// Pre-raid gear lists. Bundled data is generated by `npm run gear`; the desktop app can download newer
// lists from Settings → Check for updates, which take priority when present.
import BUNDLED from './gear.json' with { type: 'json' };

const override = (() => {
  try {
    const data = globalThis.everhart?.getGearOverride?.();
    return data?.specs && data?.items && data?.meta ? data : null;
  } catch {
    return null;
  }
})();

export const GEAR = override ?? BUNDLED;
export const GEAR_META = { ...GEAR.meta, origin: override ? 'downloaded' : 'bundled' };
